<?php
declare(strict_types=1);require_once __DIR__.'/includes/store.php';$pageTitle='Shopping cart';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token. Refresh and try again.');}$action=$_POST['action']??'';if($action==='remove'){unset($_SESSION['cart'][(int)($_POST['product_id']??0)]);}elseif($action==='update'){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($id>0){if($qty<=0)unset($_SESSION['cart'][$id]);else{try{$_SESSION['cart'][$id]=min($qty,999);}catch(Throwable $e){}}}}}redirect('cart.php');}
$cart=cart_contents();require __DIR__.'/includes/header.php';?><section class="container py-5"><h1 class="h2 mb-4">Your shopping cart</h1><?php if(!$cart['items']):?><div class="empty-state text-center p-5"><h2 class="h5">Your cart is empty</h2><p class="text-secondary">Browse our catalogue and add something you love.</p><a class="btn btn-primary" href="shop.php">Continue shopping</a></div><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Price</th><th style="width:130px">Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($cart['items'] as $item):?><tr><td><div class="d-flex align-items-center gap-3"><?php if($item['image_path']):?><img src="<?=e($item['image_path'])?>" alt="" style="width:72px;height:72px;object-fit:contain"><?php endif;?><a href="product.php?slug=<?=e($item['slug'])?>"><?=e($item['name'])?></a></div><small class="text-secondary">Available: <?= (int)$item['stock_quantity']?></small></td><td><?=money($item['price'])?></td><td><input class="form-control" type="number" min="0" max="<?= (int)$item['stock_quantity']?>" name="qty[<?= (int)$item['id']?>]" value="<?= (int)$item['quantity']?>"></td><td class="fw-semibold"><?=money($item['line_total'])?></td><td><button class="btn btn-sm btn-outline-secondary" type="submit" formaction="cart.php" formmethod="post" name="remove_id" value="<?= (int)$item['id']?>" onclick="this.form.action='cart.php';this.form.querySelector('[name=action]').value='remove';this.form.querySelector('[name=product_id]').value=this.value;">Remove</button></td></tr><?php endforeach;?></tbody></table></div><input type="hidden" name="product_id" value=""><div class="d-flex flex-wrap justify-content-between gap-3 align-items-start"><button class="btn btn-outline-primary" type="submit">Update cart</button><div class="card border-0 shadow-sm p-4" style="min-width:280px"><div class="d-flex justify-content-between"><span>Items (<?= (int)$cart['count']?>)</span><strong><?=money($cart['subtotal'])?></strong></div><div class="d-flex justify-content-between mt-2"><span>Delivery</span><span>Calculated at checkout</span></div><hr><div class="d-flex justify-content-between fs-5"><strong>Subtotal</strong><strong><?=money($cart['subtotal'])?></strong></div><a href="checkout.php" class="btn btn-primary w-100 mt-3">Proceed to checkout</a></div></div></form><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
